package diag;
import static diag.Observe.*;
import java.io.*;import java.lang.instrument.*;import java.nio.file.*;import java.security.ProtectionDomain;import java.util.*;import java.util.concurrent.atomic.AtomicLong;
import jdk.internal.org.objectweb.asm.*;import jdk.internal.org.objectweb.asm.commons.AdviceAdapter;
public final class MethodObserve {
 static volatile boolean traceStatements=false;
 static AtomicLong ids=new AtomicLong();static ThreadLocal<Object[]> active=new ThreadLocal<>();
 static final String TARGET="BenchmarkTest01000$Test#doSomething";
 static boolean selected(int run,Object key){return run>=7&&String.valueOf(key).contains(TARGET);}
 public static void premain(String path,Instrumentation inst)throws Exception{
  output=new PrintWriter(Files.newBufferedWriter(Path.of(path)));
  Runtime.getRuntime().addShutdownHook(new Thread(()->{synchronized(Observe.class){output.println("{\"event\":\"END\",\"rows\":"+rows+",\"errors\":"+errors+"}");output.close();}}));
  inst.addTransformer(new ClassFileTransformer(){public byte[] transform(ClassLoader cl,String cn,Class<?> r,ProtectionDomain pd,byte[] bytes){
   boolean ds=cn.equals("org/opentaint/dataflow/bidi/store/DemandStore"),limit=cn.equals("org/opentaint/dataflow/bidi/ap/LimitKt"),bs=cn.equals("org/opentaint/dataflow/bidi/engine/BlockRunState"),ho=cn.equals("org/opentaint/dataflow/bidi/driver/HandOff$Companion"),er=cn.equals("org/opentaint/dataflow/bidi/store/ExactDemandResults"),cs=cn.equals("org/opentaint/dataflow/bidi/engine/RunMethodCallServices");
   if(!ds&&!limit&&!bs&&!ho&&!er&&!cs)return null;
   try{ClassReader cr=new ClassReader(bytes);ClassWriter cw=new ClassWriter(cr,ClassWriter.COMPUTE_MAXS);
    cr.accept(new ClassVisitor(Opcodes.ASM8,cw){public MethodVisitor visitMethod(int acc,String name,String desc,String sig,String[]ex){MethodVisitor mv=super.visitMethod(acc,name,desc,sig,ex);
     if(ds&&name.equals("initials")&&desc.startsWith("(Lorg/opentaint/dataflow/ap/ifds/MethodEntryPoint;"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodExit(int op){if(op==ARETURN){dup();loadThis();loadArg(0);loadArg(1);loadArg(2);visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","initials","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}}};
     if(ds&&name.equals("offerDataPair"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){for(int i=0;i<6;i++)loadArg(i);visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","rowBegin","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}protected void onMethodExit(int op){visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","rowEnd","()V",false);}};
     if(limit&&name.equals("limitFacts"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){loadArg(0);loadArg(1);loadArg(2);visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","limit","(Ljava/lang/Object;Ljava/lang/Object;I)V",false);}};
     if(bs&&(acc&Opcodes.ACC_STATIC)==0&&name.startsWith("retainSummary"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){loadThis();loadArg(0);loadArg(1);visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","raw","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}};
     if(bs&&(acc&Opcodes.ACC_STATIC)==0&&name.equals("process"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){loadThis();loadArg(0);visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","process","(Ljava/lang/Object;Ljava/lang/Object;)V",false);}};
     if(bs&&(acc&Opcodes.ACC_STATIC)==0&&name.startsWith("emitAfter"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){loadThis();loadArg(0);loadArg(1);loadArg(2);visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","after","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}};
     if(er&&name.equals("add"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){loadArg(0);visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","offered","(Ljava/lang/Object;)V",false);}};
     if(ho&&name.equals("of"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodExit(int op){if(op==ARETURN){dup();loadArg(0);loadArg(1);loadArg(2);visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","handoff","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}}};
     if(cs&&name.equals("applyRecordView"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){loadThis();loadArg(0);loadArg(1);visitMethodInsn(INVOKESTATIC,"diag/MethodObserve","view","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}};
     return mv;
    }},ClassReader.EXPAND_FRAMES);System.err.println("METHOD_TRANSFORM "+cn);return cw.toByteArray();
   }catch(Throwable t){error("transform:"+cn,t);return null;}
  }});
 }
 public static void initials(Object results,Object ds,Object key,Object actual,Object policy){try{
  int run=((Number)get(policy,"run")).intValue();if(!selected(run,key))return;
  traceStatements=run==7||run==8;Object ap=field(ds,"ap");long id=ids.incrementAndGet();Object b=builder(ap,"C2_ACTUAL",run,String.valueOf(key),"ROOT");call(b,"number","query",id);call(b,"facts","actual",actual);call(b,"number","count",((Collection<?>)results).size());emit(b);
  int i=0;for(Object item:(Collection<?>)results){Object c=builder(ap,"C2_INITIAL",run,String.valueOf(key),"ROOT");call(c,"number","query",id);call(c,"premise","initial",get(item,"initial"));call(c,"text","layer",String.valueOf(get(item,"layer")));call(c,"number","index",i++);emit(c);}
 }catch(Throwable t){error("initials",t);}}
 static Object ctxBuilder(String event)throws Exception{Object[]a=active.get();Object b=builder(a[1],event,(Integer)a[5],String.valueOf(a[0]),"ROOT");call(b,"number","row",a[6]);return b;}
 public static void rowBegin(Object key,Object ops,Object member,Object raw,Object pair,Object policy){try{
  int run=((Number)get(policy,"run")).intValue();if(!selected(run,key))return;
  active.set(new Object[]{key,get(ops,"manager"),member,pair,raw,run,ids.incrementAndGet()});Object b=ctxBuilder("C5_ROW");call(b,"number","globalLimit",get(policy,"fieldLimit"));call(b,"premise","premise",member);call(b,"facts","raw",raw);call(b,"pattern","entry",get(pair,"entry"));call(b,"pattern","exit",get(pair,"exit"));emit(b);
 }catch(Throwable t){error("rowBegin",t);}}
 public static void rowEnd(){active.remove();}
 public static void limit(Object ap,Object kept,int budget){if(active.get()==null)return;try{Object b=ctxBuilder("C5_BEFORE_LIMIT");call(b,"number","budget",budget);call(b,"facts","kept",kept);emit(b);}catch(Throwable t){error("limit",t);}}
 public static void offered(Object fact){if(active.get()==null)return;try{Object b=ctxBuilder("C5_ROW_OFFERED");call(b,"facts","result",fact);emit(b);}catch(Throwable t){error("offered",t);}}
 public static void process(Object core,Object edge){if(!traceStatements)return;try{statement(core,get(edge,"premise"),get(edge,"node"),get(edge,"facts"),"PROCESS");}catch(Throwable t){error("process",t);}}
 public static void after(Object core,Object premise,Object node,Object value){if(!traceStatements)return;try{statement(core,premise,node,value,"EMIT_AFTER");}catch(Throwable t){error("after",t);}}
 static void statement(Object core,Object premise,Object node,Object value,String event)throws Exception{
  int run=((Number)get(get(core,"config"),"index")).intValue();Object key=get(core,"key");if(run>8||!selected(run,key))return;
  Object b=builder(get(core,"ap"),event,run,String.valueOf(key),String.valueOf(get(core,"scope")));call(b,"text","statement",String.valueOf(node));call(b,"number","instruction",get(get(node,"location"),"index"));call(b,"premise","premise",premise);call(b,"facts","value",value);
  if(String.valueOf(get(value,"layer")).equals("DEMAND")&&event.equals("EMIT_AFTER")){StackTraceElement[] a=Thread.currentThread().getStackTrace();StringJoiner st=new StringJoiner("\n");for(int i=2;i<Math.min(24,a.length);i++)st.add(a[i].toString());call(b,"text","stack",st.toString());}emit(b);
 }
 public static void raw(Object core,Object premise,Object raw){try{int run=((Number)get(get(core,"config"),"index")).intValue();Object key=get(core,"key");if(!selected(run,key))return;Object b=builder(get(core,"ap"),"RAW_SUMMARY",run,String.valueOf(key),String.valueOf(get(core,"scope")));call(b,"premise","premise",premise);call(b,"facts","raw",raw);emit(b);}catch(Throwable t){error("raw",t);}}
 static Object pattern(Object c)throws Exception{return Class.forName("org.opentaint.dataflow.bidi.ap.Pattern").getConstructors()[0].newInstance(get(c,"fact"),get(c,"exclusion"));}
 public static void view(Object services,Object part,Object view){try{Object core=field(services,"owner");int run=((Number)get(get(core,"config"),"index")).intValue();Object key=get(core,"key");if(!selected(run,key))return;Object b=builder(get(core,"ap"),"SAVED_VIEW",run,String.valueOf(key),String.valueOf(get(core,"scope")));call(b,"facts","input",get(part,"added"));call(b,"premise","premise",get(get(part,"ref"),"premise"));call(b,"text","callee",String.valueOf(get(part,"callee")));call(b,"pattern","viewPremise",get(view,"premise"));call(b,"pattern","viewResult",pattern(get(view,"result")));call(b,"flag","demand",get(get(view,"result"),"demand"));emit(b);}catch(Throwable t){error("view",t);}}
 public static void handoff(Object hand,Object config,Object result,Object shared){try{
  int run=((Number)get(config,"index")).intValue();if(run==8)traceStatements=false;if(run<6)return;Object ap=get(shared,"ap"),ds=get(hand,"demand");
  for(var e:((Map<?,?>)field(ds,"byMethod")).entrySet())if(String.valueOf(e.getKey()).contains(TARGET))dataRows(ap,run,e.getKey(),"ROOT",(List<?>)field(e.getValue(),"rows"),null);
  for(var e:((Map<?,?>)field(ds,"controls")).entrySet())if(String.valueOf(e.getKey()).contains(TARGET))for(Object row:(List<?>)e.getValue())control(ap,run,e.getKey(),"ROOT",row,null);
  for(Object actor:(List<?>)get(result,"analyzers")){Object key=get(actor,"key");if(!String.valueOf(key).contains(TARGET))continue;summaries(ap,run,key,"ROOT",get(actor,"summaries"));targets(ap,run,key,"ROOT",(Collection<?>)get(actor,"outgoingTargets"));}
  for(Object rec:((Map<?,?>)field(get(shared,"records"),"retainedRecords")).values())if(String.valueOf(get(rec,"method")).contains(TARGET)){
   Object b=builder(ap,"PERSISTED_AFTER",run,String.valueOf(get(rec,"method")),String.valueOf(get(rec,"scope")));call(b,"text","nativeDirection",String.valueOf(get(rec,"direction")));call(b,"premise","premise",get(rec,"premise"));call(b,"facts","facts",get(rec,"conclusion"));call(b,"text","port",String.valueOf(get(rec,"exit")));emit(b);
  }
  Object b=builder(ap,"BARRIER",run,"","");call(b,"text","direction",String.valueOf(get(config,"direction")));call(b,"number","fieldLimit",get(config,"fieldLimit"));emit(b);synchronized(Observe.class){output.flush();}
 }catch(Throwable t){error("handoff",t);}}
}

