from pathlib import Path
import json,collections,hashlib,gzip,copy
base=Path(__file__).parent;p=base/'owasp-method-cycle-final'
rows=[]
for l in (p/'trace.jsonl').open():
 try:rows.append(json.loads(l))
 except json.JSONDecodeError:pass
F={};M={}
for d in rows:
 for x in d.get('fields',[]):
  assert x['id'] not in F or F[x['id']]==x['name'];F[x['id']]=x['name']
 for x in d.get('marks',[]):
  assert x['id'] not in M or M[x['id']]==x['name'];M[x['id']]=x['name']
labels={'String#<string-bytes>':'bytes','String#bytes':'javaBytes','CharSequence#content':'content','*':'[]'}
def mark(m):return {'kind':m['kind'],'id':m.get('id'),'mx':m.get('mx',[])}
def pat(x):return {'base':x['base'],'path':x['path'],'tail':x['tail'],'E':x['E'],'mark':mark(x['mark'])}
def premise(x):return [pat(a)for a in x['members']]
def leaves(d,x):
 if x['kind']=='REACH':return [{'base':'ZERO','path':[],'tail':'EXACT','E':[],'mark':{'kind':'ZERO','id':0,'mx':[]},'layer':x['layer'],'protected':False}]
 ns={q['id']:q for q in d['nodes']}
 def walk(i,path):
  q=ns[i];result=[]
  if q.get('flowLeaf'):
   result.append({'base':x['base'],'path':path,'tail':x['tail'],'E':x['E'],'mark':{'kind':'FLOW','id':None,'mx':x.get('mx',[])},'layer':x['layer'],'protected':False})
  for family,tail in [('exact','EXACT'),('any',x['tail'])]:
   for m in q.get(family,[]):result.append({'base':x['base'],'path':path,'tail':tail,'E':x['E'] if tail!='EXACT' else [],'mark':{'kind':'CONCRETE','id':m,'mx':[]},'layer':x['layer'],'protected':False})
  for child in q['children']:result+=walk(child['node'],path+[child['field']])
  return result
 result=walk(x['root'],[])
 assert x.get('protection') is None,'Add protection decoder before using this trace'
 return result
